 snapshot=data;applyTheme();$('pair-page').hidden=true;$('workspace').hidden=false;$('device-title').textContent=data.deviceName;$('device-subtitle').textContent=data.system+' '+data.systemVersion;$('permission-label').textContent='权限 · '+(window.remotePermission==='workspace'?'项目工作区':'只读设备概况');$('device-version').textContent='Dylix '+data.version+' · '+data.build;$('build-state').textContent=data.buildRunning?'正在构建':'就绪';$('default-sdk').textContent='iOS '+data.defaultSDK;$('minimum-os').textContent='最低系统 iOS '+data.minimumOS;$('sdk-count').textContent=data.sdk.join(' / ');$('footer-device').textContent=data.deviceName;$('server-address').textContent=location.host;setConnectionStatus('connected');if(selected==='editor')resumeAutoSave();$('last-sync').textContent='同步于 '+new Date().toLocaleTimeString();$('workspace-message').textContent='';
