function showJob(job){currentTask=job;$('task-panel').hidden=false;$('task-status').textContent=({running:'执行中',awaiting_confirmation:'等待确认',completed:'已完成',failed:'执行失败',cancelled:'已取消'}[job.state]||job.state)+' · '+job.action;$('cancel-task').disabled=['completed','failed','cancelled'].includes(job.state);$('task-log').textContent=job.live?.log||job.log||job.error||job.cancellation?.message||'';$('task-progress').hidden=typeof job.progress!=='number';if(typeof job.progress==='number')$('task-progress').value=job.progress;}
async function run(action,args={},options={}){
 if(window.remotePermission!=='workspace')throw new Error('当前配对只有概况权限，请断开后申请工作区权限');
 let response=await api('/api/v1/workspace',{action,projectID:options.projectID??projectID,arguments:args});let job=response.data;
 if(job.error&&!job.id)throw new Error(job.error);
 const started=Date.now();while(true){
  if(!options.quiet)showJob(job);if(options.onUpdate)options.onUpdate(job);
  if(job.state==='completed')return job.result||{};if(job.state==='failed'||job.state==='cancelled')throw new Error(job.error||'任务已取消');
  if(job.state==='awaiting_confirmation'){const accepted=await confirmJob(job);response=await api('/api/v1/jobs/confirm',{id:job.id,nonce:job.nonce,accepted});job=response.data;continue;}
  if(Date.now()-started>30*60*1000)throw new Error('界面等待已达30分钟，请在任务中心核对实际状态');
  await wait(action==='ai_send'?250:500);response=await api('/api/v1/jobs/get',{id:job.id});job=response.data;if(job.error&&!job.state)throw new Error(job.error);
 }
}
