function inlineMarkdown(parent,text){for(const part of text.split(/(\*\*[^*]+\*\*|`[^`]+`|\[[^\]]+\]\(https?:\/\/[^\s)]+\))/g)){const link=/^\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)$/.exec(part);if(link){const a=node('a',link[1]);a.href=link[2];a.target='_blank';a.rel='noopener noreferrer';parent.append(a);}else if(part.startsWith('**')&&part.endsWith('**'))parent.append(node('strong',part.slice(2,-2)));else if(part.startsWith('`')&&part.endsWith('`'))parent.append(node('code',part.slice(1,-1)));else parent.append(document.createTextNode(part));}}
