// Reuse completed Markdown blocks. A stream update only replaces changed tail nodes.
function updateMarkdown(parent,text){const next=[...markdown(text).childNodes],old=[...parent.childNodes];for(let i=0;i<next.length;i++){if(old[i]&&old[i].tagName===next[i].tagName&&old[i].dataset.source===next[i].dataset.source)continue;if(old[i])parent.replaceChild(next[i],old[i]);else parent.append(next[i]);}for(let i=next.length;i<old.length;i++)old[i].remove();}
